-- Dependency-local activation, independent initial stocks and result-confirmed uses.
UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='use_resources' THEN jsonb_set(f,'{fields}',COALESCE(f->'fields','[]'::jsonb) || (SELECT COALESCE(jsonb_agg(n),'[]'::jsonb) FROM jsonb_array_elements($fields$[{"key": "initial_charges", "name": "Начальный запас зарядов", "type": "object", "fields": [{"key": "mode", "name": "Как определить запас", "type": "select", "options": [{"value": "fixed", "label": "Заданное число"}, {"value": "roll", "label": "Бросок костей"}]}, {"key": "value", "name": "Начальное число зарядов", "type": "int", "min": 0, "max": 100}, {"key": "formula", "name": "Формула начального запаса", "type": "text", "hint": "Бросок выполняется один раз при добавлении экземпляра, например 1к8+1."}]}, {"key": "activation", "name": "Когда действует свойство", "type": "select", "emptyLabel": "Как у предмета", "hint": "Переопределяет только эту зависимость. Настройка на персонажа всё равно требуется, если указана у предмета.", "options": [{"value": "carried", "label": "Пока предмет при персонаже"}, {"value": "equipped", "label": "Когда предмет экипирован"}]}]$fields$::jsonb) n WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(f->'fields') old WHERE old->>'key'=n->>'key'))) ELSE f END ORDER BY ord) FROM jsonb_array_elements(fields) WITH ORDINALITY x(f,ord)) WHERE id=19;

UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='derived_effects' THEN jsonb_set(f,'{fields}',COALESCE(f->'fields','[]'::jsonb) || (SELECT COALESCE(jsonb_agg(n),'[]'::jsonb) FROM jsonb_array_elements($fields$[{"key": "activation", "name": "Когда действует свойство", "type": "select", "emptyLabel": "Как у предмета", "hint": "Переопределяет только эту зависимость. Настройка на персонажа всё равно требуется, если указана у предмета.", "options": [{"value": "carried", "label": "Пока предмет при персонаже"}, {"value": "equipped", "label": "Когда предмет экипирован"}]}]$fields$::jsonb) n WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(f->'fields') old WHERE old->>'key'=n->>'key'))) ELSE f END ORDER BY ord) FROM jsonb_array_elements(fields) WITH ORDINALITY x(f,ord)) WHERE id=19;

UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='roll_triggers' THEN jsonb_set(f,'{fields}',COALESCE(f->'fields','[]'::jsonb) || (SELECT COALESCE(jsonb_agg(n),'[]'::jsonb) FROM jsonb_array_elements($fields$[{"key": "activation", "name": "Когда действует свойство", "type": "select", "emptyLabel": "Как у предмета", "hint": "Переопределяет только эту зависимость. Настройка на персонажа всё равно требуется, если указана у предмета.", "options": [{"value": "carried", "label": "Пока предмет при персонаже"}, {"value": "equipped", "label": "Когда предмет экипирован"}]}, {"key": "use_key", "name": "Связанное применение", "type": "text", "hint": "Свойство из блока «Применение по условию»: задаёт ресурс, цену и ожидание. При перебросе расходует именно его."}]$fields$::jsonb) n WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(f->'fields') old WHERE old->>'key'=n->>'key'))) ELSE f END ORDER BY ord) FROM jsonb_array_elements(fields) WITH ORDINALITY x(f,ord)) WHERE id=19;

UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='confirmed_uses' THEN jsonb_set(f,'{fields}',COALESCE(f->'fields','[]'::jsonb) || (SELECT COALESCE(jsonb_agg(n),'[]'::jsonb) FROM jsonb_array_elements($fields$[{"key": "activation", "name": "Когда действует свойство", "type": "select", "emptyLabel": "Как у предмета", "hint": "Переопределяет только эту зависимость. Настройка на персонажа всё равно требуется, если указана у предмета.", "options": [{"value": "carried", "label": "Пока предмет при персонаже"}, {"value": "equipped", "label": "Когда предмет экипирован"}]}, {"key": "cooldown_dawns", "name": "Рассветов до следующего применения", "type": "int", "min": 0, "max": 100, "hint": "0 — без ожидания. Ожидание отдельно от ресурса: рассвет сам по себе не возвращает потраченные заряды."}, {"key": "show_resource", "name": "Показывать заряды внутри панели", "type": "bool", "hint": "Те же ячейки ресурса появятся в панели свойства вместо отдельной строки над ней."}]$fields$::jsonb) n WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(f->'fields') old WHERE old->>'key'=n->>'key'))) ELSE f END ORDER BY ord) FROM jsonb_array_elements(fields) WITH ORDINALITY x(f,ord)) WHERE id=19;

UPDATE dndshare.item_type SET fields=(SELECT jsonb_agg(CASE WHEN f->>'key'='roll_triggers' THEN jsonb_set(f,'{fields}',(SELECT jsonb_agg(CASE WHEN c->>'key'='event' THEN $event${"name": "Событие", "key": "event", "type": "select", "options": [{"label": "Натуральная 1", "value": "natural_one"}, {"value": "any", "label": "После любого результата"}], "default": "natural_one"}$event$::jsonb ELSE c END ORDER BY n) FROM jsonb_array_elements(f->'fields') WITH ORDINALITY y(c,n))) ELSE f END ORDER BY ord) FROM jsonb_array_elements(fields) WITH ORDINALITY x(f,ord)) WHERE id=19;

UPDATE dndshare.item SET data=jsonb_set(data,'{activation}','"carried"'::jsonb) || jsonb_build_object('use_resources',COALESCE(data->'use_resources','[]'::jsonb) || $use_resources$[{"key": "luck", "title": "Удача", "max_use": 1, "dawn_recovery": {"mode": "full"}, "activation": "carried"}, {"key": "wishes", "title": "Желания", "initial_charges": {"mode": "roll", "formula": "1к4−1"}, "activation": "carried"}]$use_resources$::jsonb) || jsonb_build_object('confirmed_uses',COALESCE(data->'confirmed_uses','[]'::jsonb) || $confirmed_uses$[{"key": "luck", "title": "Удача", "description": "<p>Перебросьте один бросок атаки, проверку характеристики или спасбросок. Используйте второй результат. Действие не требуется.</p>", "requirements": ["Меч при персонаже", "Один раз до следующего рассвета"], "confirm_label": "Отметить переброс вне приложения", "resource_key": "luck", "resource_cost": 1, "activation": "carried", "show_resource": true}, {"key": "wish", "title": "Желание", "description": "<p>Действием сотворите заклинание «Желание». Потраченные заряды не восстанавливаются.</p>", "requirements": ["Держите меч в руке", "Не чаще одного раза до следующего рассвета"], "confirm_label": "Сотворить желание", "resource_key": "wishes", "resource_cost": 1, "cooldown_dawns": 1, "activation": "equipped", "show_resource": true}]$confirmed_uses$::jsonb) || jsonb_build_object('roll_triggers',COALESCE(data->'roll_triggers','[]'::jsonb) || $roll_triggers$[{"event": "any", "action": "reroll", "scopes": ["attack", "ability_check", "saving_throw", "initiative"], "label": "Удача — Клинок удачи", "use_key": "luck", "activation": "carried"}]$roll_triggers$::jsonb) || jsonb_build_object('derived_effects',COALESCE(data->'derived_effects','[]'::jsonb) || $derived_effects$[{"kind": "save_bonus", "value": 1, "activation": "carried"}]$derived_effects$::jsonb) WHERE id=171 AND name='Клинок удачи' AND type_id=19 AND user_id IS NULL AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(data->'confirmed_uses','[]'::jsonb)) r WHERE r->>'key'='luck');
